// Filter to only unprocessed rows (status column is empty) that have a URL.
// Also capture the row number for later sheet updates.
const results = [];
for (const item of $input.all()) {
  const url = (item.json.url || '').trim();
  const status = (item.json.status || '').trim();
  const processedAt = (item.json.processed_at || '').trim();

  // Skip rows without a URL or that already have a status
  if (!url) continue;
  if (status && status !== 'processing') continue;

  // Crash recovery: retry rows stuck in 'processing' for >30 min
  if (status === 'processing' && processedAt) {
    const stuckSince = new Date(processedAt).getTime();
    if (Date.now() - stuckSince < 30 * 60 * 1000) continue;
  }

  results.push({ json: { ...item.json, _row_number: item.json.row_number } });
}
return results;

// Extract og:image or twitter:image from raw HTML meta tags,
// then strip HTML to plain text for LLM.
const item = $input.first();
const html = item.json.data || item.json.body || '';
const originalData = $('Process One at a Time').item.json;

if (!html || html.length < 100) {
  throw new Error('No extractable content at URL');
}

// --- Extract og:image / twitter:image ---
let ogImage = '';
const ogMatch = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
  || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
if (ogMatch) ogImage = ogMatch[1];

if (!ogImage) {
  const twMatch = html.match(/<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i)
    || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i);
  if (twMatch) ogImage = twMatch[1];
}

// --- Strip HTML to plain text ---
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#?\w+;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const MAX_CHARS = 8000;
if (text.length > MAX_CHARS) {
  text = text.slice(0, MAX_CHARS) + '... [truncated]';
}

return [{
  json: {
    url: originalData.url,
    note: originalData.note || '',
    _row_number: originalData._row_number,
    og_image_url: ogImage,
    page_text: text
  }
}];

