// Parse LLM JSON response, generate slug, merge og:image.
const llmOutput = $input.first().json;
const prevData = $('Extract Image & Strip HTML').first().json;

// Get the raw text response from the LLM node
let raw = llmOutput.response || llmOutput.text || llmOutput.message?.content || JSON.stringify(llmOutput);

// Strip markdown code fences if present
const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
if (fenceMatch) raw = fenceMatch[1];

let parsed;
try {
  parsed = JSON.parse(raw.trim());
} catch (e) {
  throw new Error('LLM returned invalid JSON: ' + e.message + ' | Raw: ' + raw.slice(0, 200));
}

// Validate required fields
if (!parsed.title || !parsed.event_start_at) {
  throw new Error('Missing required fields: ' + (!parsed.title ? 'title ' : '') + (!parsed.event_start_at ? 'event_start_at' : ''));
}

// Slugify matching src/lib/utils.ts:63-69
function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

const dateSlug = (parsed.event_start_at || '').slice(0, 10);
const slug = slugify(parsed.title + '-' + dateSlug);

// Merge image: prefer og:image extracted from HTML, fall back to LLM-extracted
const image_url = prevData.og_image_url || parsed.image_url || null;

// Ensure tags is an array
let tags = parsed.tags || [];
if (typeof tags === 'string') {
  tags = tags.split(',').map(t => t.trim()).filter(Boolean);
}

return [{
  json: {
    slug,
    status: 'pending',
    title: parsed.title,
    summary: parsed.summary || '',
    description: parsed.description || '',
    source_url: prevData.url,
    source_name: parsed.source_name || '',
    source_event_id: parsed.source_event_id || '',
    event_start_at: parsed.event_start_at,
    event_end_at: parsed.event_end_at || null,
    timezone: 'Asia/Kolkata',
    venue_name: parsed.venue_name || '',
    venue_address: parsed.venue_address || '',
    neighborhood: parsed.neighborhood || '',
    category: parsed.category || 'General',
    price_text: parsed.price_text || '',
    image_url,
    reason: parsed.reason || '',
    suggestion: parsed.suggestion || '',
    score: parsed.score != null ? Number(parsed.score) : null,
    tags,
    _row_number: prevData._row_number
  }
}];

// Format error message from any failed upstream node.
const error = $input.first().json;
const originalData = $('Process One at a Time').item.json;

let message = 'Unknown error';
if (error.error?.message) message = error.error.message;
else if (error.message) message = error.message;
else if (typeof error === 'string') message = error;

// Truncate long error messages
if (message.length > 200) message = message.slice(0, 200) + '...';

return [{
  json: {
    _row_number: originalData._row_number,
    error_message: message
  }
}];
